<?php renderBreadcrumbs($seo) ?><?php if(!visibleArticle($article)): ?><div class="notice notice">此文章未公开，仅管理员可预览。</div><?php endif ?><div class="content-with-sidebar"><article class="panel detail-panel article-detail"><span class="article-tag"><?= e($article['category_name']) ?> · <?= kindLabel($article['kind']) ?></span><h1><?= e($article['title']) ?></h1><div class="detail-meta"><time><?= e(substr($article['created_at'],0,10)) ?></time><span><?= e(siteName()) ?></span><?php if($article['is_demo']): ?><span class="demo-label">原创演示内容</span><?php endif ?></div><?php if($article['summary']): ?><p class="article-summary"><?= e($article['summary']) ?></p><?php endif ?><?php foreach($images as $image): ?><img class="article-cover" src="/media/<?= $image['id'] ?>/" alt="<?= e($article['title']) ?>的封面"><?php endforeach ?><div class="prose"><?= articleBodyHtml($article) ?></div><div class="article-bottom"><a href="<?= $base ?>">返回<?= kindLabel($article['kind']) ?></a><?php if(currentAdmin()): ?><a href="<?= e(adminUrl('articles',['edit'=>$article['id'],'kind'=>$article['kind']])) ?>">编辑文章</a><?php endif ?></div></article><aside class="side-stack"><section class="panel side-card"><h2>同主题阅读</h2><ul class="text-list"><?php foreach($related['items'] as $other): if($other['id']===$article['id']) continue; ?><li><a href="<?= articleUrl($other) ?>"><?= e($other['title']) ?></a></li><?php endforeach ?></ul></section><section class="panel side-card"><h2>查找当地服务</h2><p>按分类和城市查找维修服务。</p><a class="button full" href="/fen-lei-xin-xi/">浏览服务</a></section></aside></div>
